const reduced=matchMedia('(prefers-reduced-motion: reduce)');let paused=reduced.matches;
const motion=document.querySelector('#motion');function updateMotion(){document.documentElement.classList.toggle('motion-paused',paused);motion.setAttribute('aria-pressed',String(paused));motion.textContent=paused?'Play motion ▷':'Pause motion Ⅱ'}motion.addEventListener('click',()=>{paused=!paused;updateMotion()});reduced.addEventListener('change',()=>{paused=reduced.matches;updateMotion()});updateMotion();
if(!reduced.matches){document.documentElement.classList.add('js-motion');const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}},{threshold:.06});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));}
const stage=document.querySelector('.project-stage');let progress=0,frameId=0;
function renderStage(){frameId=0;if(paused||innerWidth<801){stage.style.transform='';return}const r=document.querySelector('.hero').getBoundingClientRect();progress=Math.max(0,Math.min(1,-r.top/r.height));stage.style.transform=`translateY(${progress*-45}px)`}
addEventListener('scroll',()=>{if(!frameId)frameId=requestAnimationFrame(renderStage)},{passive:true});addEventListener('resize',renderStage);motion.addEventListener('click',renderStage);
document.querySelectorAll('.questions details').forEach(detail=>detail.addEventListener('toggle',()=>{if(detail.open)document.querySelectorAll('.questions details').forEach(other=>{if(other!==detail)other.open=false})}));
